scenario.irule:
when HTTP_RESPONSE { HTML::enable; log local0. "encoded=[HTML::encode {<x>&"'}]" }
when HTML_TAG_MATCHED { if {[HTML::tag name] eq "html"} { HTML::disable; HTML::enable }; if {[HTML::tag name] eq "title"} { HTML::tag prepend {<!--title-start-->}; HTML::tag append {<!--title-end-->} }; if {[string trimleft [HTML::tag name] /] eq "p"} { HTML::tag remove }; if {[HTML::tag name] eq "br"} { HTML::tag append {<!--br-marker-->} } }
when HTML_COMMENT_MATCHED { if {[HTML::comment] eq {<!--remove-->}} { HTML::comment remove } }
